CREATE TABLE workforce_payload(org_id TEXT NOT NULL REFERENCES organization(id),id TEXT NOT NULL,owner_kind TEXT NOT NULL CHECK(owner_kind IN('legal_entity','org_unit','employee_identifier','education_record','job_assignment','structure_change')),owner_id TEXT NOT NULL,employee_id TEXT,record_id TEXT NOT NULL CHECK(record_id=owner_id),version_id TEXT NOT NULL CHECK(version_id=id),purpose TEXT NOT NULL CHECK(purpose='pii'),schema_type TEXT NOT NULL CHECK(schema_type IN('pii.legal_entity_label.v1','pii.org_unit_label.v1','pii.employee_identifier.v1','pii.education.v1','pii.job_assignment_position.v1','org.structure.reason.v1')),schema_version INTEGER NOT NULL CHECK(schema_version=1),format_version INTEGER NOT NULL CHECK(format_version=1),algorithm TEXT NOT NULL CHECK(algorithm='A256GCM-RANDOMNONCE'),dek_id TEXT NOT NULL,kek_id TEXT NOT NULL CHECK(length(kek_id)>0),kek_version INTEGER NOT NULL CHECK(kek_version>0),wrapped_dek BYTEA NOT NULL CHECK(octet_length(wrapped_dek)>0),sealed_bytes BYTEA NOT NULL CHECK(octet_length(sealed_bytes)>=28),created_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,owner_kind,owner_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),CHECK((owner_kind IN('legal_entity','org_unit','structure_change') AND employee_id IS NULL) OR (owner_kind IN('employee_identifier','education_record','job_assignment') AND employee_id IS NOT NULL)));
CREATE TRIGGER rewrap_block_workforce_payload BEFORE INSERT ON workforce_payload FOR EACH ROW EXECUTE FUNCTION key_rewrap_write_guard('pii');
CREATE TABLE legal_entity(org_id TEXT NOT NULL REFERENCES organization(id),id TEXT NOT NULL,code TEXT NOT NULL CHECK(length(code) BETWEEN 1 AND 64),kind TEXT NOT NULL CHECK(kind='branch_company'),PRIMARY KEY(org_id,id),UNIQUE(org_id,code));
CREATE TABLE legal_entity_version(org_id TEXT NOT NULL,id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,payload_kind TEXT NOT NULL DEFAULT 'legal_entity' CHECK(payload_kind='legal_entity'),label_payload_id TEXT NOT NULL,valid_from DATE NOT NULL,valid_to DATE CHECK(valid_to IS NULL OR valid_from<valid_to),revision BIGINT NOT NULL CHECK(revision>0),supersedes_id TEXT,change_id TEXT,PRIMARY KEY(org_id,id),UNIQUE(org_id,legal_entity_id,revision),FOREIGN KEY(org_id,legal_entity_id) REFERENCES legal_entity(org_id,id),FOREIGN KEY(org_id,payload_kind,legal_entity_id,label_payload_id) REFERENCES workforce_payload(org_id,owner_kind,owner_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,supersedes_id) REFERENCES legal_entity_version(org_id,id),FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),CHECK(supersedes_id IS NULL OR supersedes_id<>id));
CREATE UNIQUE INDEX legal_entity_version_current ON legal_entity_version(org_id,legal_entity_id) WHERE valid_to IS NULL;
