CREATE TABLE org_unit_version(org_id TEXT NOT NULL,id TEXT NOT NULL,org_unit_id TEXT NOT NULL,payload_kind TEXT NOT NULL DEFAULT 'org_unit' CHECK(payload_kind='org_unit'),label_payload_id TEXT NOT NULL,valid_from DATE NOT NULL,valid_to DATE CHECK(valid_to IS NULL OR valid_from<valid_to),revision BIGINT NOT NULL CHECK(revision>0),supersedes_id TEXT,change_id TEXT,PRIMARY KEY(org_id,id),UNIQUE(org_id,org_unit_id,revision),FOREIGN KEY(org_id,org_unit_id) REFERENCES org_unit(org_id,id),FOREIGN KEY(org_id,payload_kind,org_unit_id,label_payload_id) REFERENCES workforce_payload(org_id,owner_kind,owner_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,supersedes_id) REFERENCES org_unit_version(org_id,id),FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),CHECK(supersedes_id IS NULL OR supersedes_id<>id));
