CREATE TABLE employee_business_identifier(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'staff_code' CHECK(kind='staff_code'),lookup_key_id TEXT NOT NULL,lookup_key_version INTEGER NOT NULL CHECK(lookup_key_version>0),lookup_digest BYTEA NOT NULL CHECK(octet_length(lookup_digest)=32),payload_kind TEXT NOT NULL DEFAULT 'employee_identifier' CHECK(payload_kind='employee_identifier'),payload_id TEXT NOT NULL,valid_from DATE NOT NULL,valid_to DATE CHECK(valid_to IS NULL OR valid_from<valid_to),recorded_at TIMESTAMPTZ NOT NULL,change_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),supersedes_id TEXT,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,kind,lookup_key_version,lookup_digest,employee_id) REFERENCES employee_identifier_owner(org_id,kind,key_version,digest,employee_id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,payload_kind,id,payload_id) REFERENCES workforce_payload(org_id,owner_kind,owner_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),FOREIGN KEY(org_id,supersedes_id) REFERENCES employee_business_identifier(org_id,id),CHECK(supersedes_id IS NULL OR supersedes_id<>id));
CREATE TABLE employment_spell(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,location_code TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('hire','rehire','transfer')),valid_from DATE NOT NULL,valid_to DATE CHECK(valid_to IS NULL OR valid_from<valid_to),recorded_at TIMESTAMPTZ NOT NULL,change_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),supersedes_id TEXT,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,legal_entity_id) REFERENCES legal_entity(org_id,id),FOREIGN KEY(location_code) REFERENCES work_location(code),FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),FOREIGN KEY(org_id,supersedes_id) REFERENCES employment_spell(org_id,id),CHECK(supersedes_id IS NULL OR supersedes_id<>id));
