CREATE TABLE compensation_adjustment_batch(org_id TEXT NOT NULL,id TEXT NOT NULL,business_code TEXT NOT NULL,cycle_year BIGINT NOT NULL CHECK(cycle_year BETWEEN 2000 AND 9999),adjustment_type TEXT NOT NULL CHECK(adjustment_type IN('normal','special')),legal_entity_id TEXT NOT NULL,default_effective_date DATE,state TEXT NOT NULL CHECK(state IN('draft','activation_blocked','activation_conflict','activated','withdrawn')),revision BIGINT NOT NULL CHECK(revision>0),manifest_digest TEXT,creator_subject_id TEXT NOT NULL,created_at BIGINT NOT NULL,activated_at BIGINT,PRIMARY KEY(org_id,id),UNIQUE(org_id,business_code),FOREIGN KEY(org_id,legal_entity_id) REFERENCES legal_entity(org_id,id),FOREIGN KEY(org_id,creator_subject_id) REFERENCES subject(org_id,id),CHECK((adjustment_type='normal' AND default_effective_date IS NOT NULL) OR (adjustment_type='special' AND default_effective_date IS NULL)));
CREATE TABLE compensation_batch_service(org_id TEXT NOT NULL,batch_id TEXT NOT NULL,subject_id TEXT NOT NULL,PRIMARY KEY(org_id,batch_id),UNIQUE(org_id,subject_id),FOREIGN KEY(org_id,batch_id) REFERENCES compensation_adjustment_batch(org_id,id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id));
CREATE TABLE compensation_special_reason(org_id TEXT NOT NULL REFERENCES organization(id),code TEXT NOT NULL CHECK(length(code) BETWEEN 1 AND 64),label TEXT NOT NULL CHECK(length(label) BETWEEN 1 AND 200),active BOOLEAN NOT NULL,PRIMARY KEY(org_id,code));
CREATE TABLE compensation_batch_payload(org_id TEXT NOT NULL,id TEXT NOT NULL,batch_id TEXT NOT NULL,batch_revision BIGINT NOT NULL CHECK(batch_revision>1),employee_id TEXT NOT NULL,record_id TEXT NOT NULL,version_id TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose='financial'),schema_type TEXT NOT NULL CHECK(schema_type='compensation.batch_line.v1'),schema_version BIGINT NOT NULL CHECK(schema_version=1),format_version BIGINT NOT NULL CHECK(format_version=1),algorithm TEXT NOT NULL CHECK(algorithm='A256GCM-RANDOMNONCE'),dek_id TEXT NOT NULL,kek_id TEXT NOT NULL CHECK(length(kek_id)>0),kek_version BIGINT NOT NULL CHECK(kek_version>0),wrapped_dek BYTEA NOT NULL CHECK(octet_length(wrapped_dek)>0),sealed_bytes BYTEA NOT NULL CHECK(octet_length(sealed_bytes)>=28),created_at BIGINT NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,batch_id,batch_revision,employee_id),FOREIGN KEY(org_id,batch_id) REFERENCES compensation_adjustment_batch(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),CHECK(record_id=id AND version_id=id));
CREATE TRIGGER rewrap_block_compensation_batch_payload BEFORE INSERT ON compensation_batch_payload FOR EACH ROW EXECUTE FUNCTION key_rewrap_write_guard('financial');
CREATE TABLE compensation_batch_import_candidate(org_id TEXT NOT NULL,id TEXT NOT NULL,batch_id TEXT NOT NULL,subject_id TEXT NOT NULL,base_revision BIGINT NOT NULL CHECK(base_revision>0),state TEXT NOT NULL CHECK(state IN('valid','invalid','applied','expired')),line_count BIGINT NOT NULL CHECK(line_count BETWEEN 0 AND 500),digest BYTEA NOT NULL CHECK(octet_length(digest)=32),record_id TEXT NOT NULL CHECK(record_id=id),version_id TEXT NOT NULL CHECK(version_id=id),purpose TEXT NOT NULL CHECK(purpose='financial'),schema_type TEXT NOT NULL CHECK(schema_type='compensation.batch_import.v1'),schema_version BIGINT NOT NULL CHECK(schema_version=1),format_version BIGINT NOT NULL CHECK(format_version=1),algorithm TEXT NOT NULL CHECK(algorithm='A256GCM-RANDOMNONCE'),dek_id TEXT NOT NULL,kek_id TEXT NOT NULL CHECK(length(kek_id)>0),kek_version BIGINT NOT NULL CHECK(kek_version>0),wrapped_dek BYTEA NOT NULL CHECK(octet_length(wrapped_dek)>0),sealed_bytes BYTEA NOT NULL CHECK(octet_length(sealed_bytes)>=28),created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL CHECK(expires_at>created_at),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,batch_id) REFERENCES compensation_adjustment_batch(org_id,id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id));
CREATE UNIQUE INDEX compensation_batch_import_candidate_key ON compensation_batch_import_candidate(org_id,subject_id,id);
CREATE TRIGGER rewrap_block_compensation_batch_import_candidate BEFORE INSERT ON compensation_batch_import_candidate FOR EACH ROW EXECUTE FUNCTION key_rewrap_write_guard('financial');
CREATE TABLE compensation_batch_line(org_id TEXT NOT NULL,batch_id TEXT NOT NULL,batch_revision BIGINT NOT NULL CHECK(batch_revision>1),id TEXT NOT NULL,employee_id TEXT NOT NULL,payload_id TEXT NOT NULL,result TEXT NOT NULL CHECK(result IN('changed','no_change')),ordinal BIGINT NOT NULL CHECK(ordinal BETWEEN 0 AND 499),PRIMARY KEY(org_id,batch_id,batch_revision,id),UNIQUE(org_id,batch_id,batch_revision,employee_id),UNIQUE(org_id,batch_id,batch_revision,ordinal),FOREIGN KEY(org_id,batch_id) REFERENCES compensation_adjustment_batch(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,payload_id) REFERENCES compensation_batch_payload(org_id,id));
CREATE TABLE compensation_batch_activation(org_id TEXT NOT NULL,batch_id TEXT NOT NULL,activated_at BIGINT NOT NULL,subject_id TEXT NOT NULL,manifest_digest TEXT NOT NULL,PRIMARY KEY(org_id,batch_id),FOREIGN KEY(org_id,batch_id) REFERENCES compensation_adjustment_batch(org_id,id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id));
CREATE TABLE compensation_batch_state_history(org_id TEXT NOT NULL,batch_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),state TEXT NOT NULL CHECK(state IN('draft','submitted_preparing','activation_blocked','activation_conflict','activated','withdrawn','retired')),recorded_at BIGINT NOT NULL,subject_id TEXT NOT NULL,PRIMARY KEY(org_id,batch_id,revision,state),FOREIGN KEY(org_id,batch_id) REFERENCES compensation_adjustment_batch(org_id,id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id));
CREATE TABLE compensation_batch_event(org_id TEXT NOT NULL,batch_id TEXT NOT NULL,event_id TEXT NOT NULL,employee_id TEXT NOT NULL,effective_date DATE NOT NULL,counts_as_adjustment BOOLEAN NOT NULL,PRIMARY KEY(org_id,batch_id,event_id),UNIQUE(org_id,event_id),FOREIGN KEY(org_id,batch_id) REFERENCES compensation_adjustment_batch(org_id,id),FOREIGN KEY(org_id,event_id) REFERENCES compensation_event(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id));
CREATE TABLE compensation_batch_correction_counter(org_id TEXT NOT NULL,cycle_year BIGINT NOT NULL,adjustment_type TEXT NOT NULL CHECK(adjustment_type IN('normal','special')),next_sequence BIGINT NOT NULL CHECK(next_sequence>0),PRIMARY KEY(org_id,cycle_year,adjustment_type),FOREIGN KEY(org_id) REFERENCES organization(id));
CREATE TABLE compensation_batch_correction(org_id TEXT NOT NULL,id TEXT NOT NULL,business_code TEXT NOT NULL,corrects_batch_id TEXT NOT NULL,cycle_year BIGINT NOT NULL,adjustment_type TEXT NOT NULL CHECK(adjustment_type IN('normal','special')),manifest_digest TEXT NOT NULL,subject_id TEXT NOT NULL,activated_at BIGINT NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,business_code),FOREIGN KEY(org_id,corrects_batch_id) REFERENCES compensation_adjustment_batch(org_id,id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id));
CREATE TABLE salary_range(org_id TEXT NOT NULL,id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,location_code TEXT NOT NULL,job_family_id TEXT NOT NULL,career_level_id TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency IN('CNY','JPY')),valid_from DATE NOT NULL,valid_to DATE CHECK(valid_to IS NULL OR valid_to>valid_from),payload_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,legal_entity_id) REFERENCES legal_entity(org_id,id),FOREIGN KEY(location_code) REFERENCES work_location(code),FOREIGN KEY(org_id,job_family_id) REFERENCES job_family(org_id,id),FOREIGN KEY(org_id,career_level_id) REFERENCES career_level(org_id,id));
CREATE TABLE salary_range_payload(org_id TEXT NOT NULL,id TEXT NOT NULL,range_id TEXT NOT NULL,record_id TEXT NOT NULL CHECK(record_id=range_id),version_id TEXT NOT NULL CHECK(version_id=id),purpose TEXT NOT NULL CHECK(purpose='financial'),schema_type TEXT NOT NULL CHECK(schema_type='compensation.salary_range.v1'),schema_version BIGINT NOT NULL CHECK(schema_version=1),format_version BIGINT NOT NULL CHECK(format_version=1),algorithm TEXT NOT NULL CHECK(algorithm='A256GCM-RANDOMNONCE'),dek_id TEXT NOT NULL,kek_id TEXT NOT NULL CHECK(length(kek_id)>0),kek_version BIGINT NOT NULL CHECK(kek_version>0),wrapped_dek BYTEA NOT NULL CHECK(octet_length(wrapped_dek)>0),sealed_bytes BYTEA NOT NULL CHECK(octet_length(sealed_bytes)>=28),created_at BIGINT NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,range_id,id),FOREIGN KEY(org_id,range_id) REFERENCES salary_range(org_id,id) DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE salary_range ADD CONSTRAINT salary_range_payload_owner FOREIGN KEY(org_id,id,payload_id) REFERENCES salary_range_payload(org_id,range_id,id) DEFERRABLE INITIALLY DEFERRED;
