CREATE FUNCTION compensation_batch_payload_update_guard() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable compensation fact'; END IF; IF ROW(NEW.org_id,NEW.id,NEW.batch_id,NEW.batch_revision,NEW.employee_id,NEW.record_id,NEW.version_id,NEW.purpose,NEW.schema_type,NEW.schema_version,NEW.format_version,NEW.algorithm,NEW.dek_id,NEW.sealed_bytes,NEW.created_at) IS DISTINCT FROM ROW(OLD.org_id,OLD.id,OLD.batch_id,OLD.batch_revision,OLD.employee_id,OLD.record_id,OLD.version_id,OLD.purpose,OLD.schema_type,OLD.schema_version,OLD.format_version,OLD.algorithm,OLD.dek_id,OLD.sealed_bytes,OLD.created_at) OR NOT EXISTS(SELECT 1 FROM key_rewrap_job WHERE org_id=NEW.org_id AND domain='financial' AND state='migrating' AND target_kek_id=NEW.kek_id AND target_kek_version=NEW.kek_version) THEN RAISE EXCEPTION 'immutable compensation fact'; END IF; RETURN NEW; END$$;
CREATE TRIGGER compensation_batch_payload_update_guard BEFORE UPDATE OR DELETE ON compensation_batch_payload FOR EACH ROW EXECUTE FUNCTION compensation_batch_payload_update_guard();
CREATE TABLE compensation_batch_command_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('OP-COMP-07','OP-COMP-08','OP-COMP-09','OP-COMP-10','OP-COMP-11')),key TEXT NOT NULL,digest BYTEA NOT NULL CHECK(octet_length(digest)=32),batch_id TEXT NOT NULL,result_revision BIGINT NOT NULL CHECK(result_revision>0),recorded_at BIGINT NOT NULL,PRIMARY KEY(org_id,subject_id,operation,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,batch_id) REFERENCES compensation_adjustment_batch(org_id,id));
CREATE TABLE salary_range_command_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,key TEXT NOT NULL,digest BYTEA NOT NULL CHECK(octet_length(digest)=32),recorded_at BIGINT NOT NULL,PRIMARY KEY(org_id,subject_id,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id));
CREATE FUNCTION salary_range_payload_update_guard() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable salary range fact'; END IF; IF ROW(NEW.org_id,NEW.id,NEW.range_id,NEW.record_id,NEW.version_id,NEW.purpose,NEW.schema_type,NEW.schema_version,NEW.format_version,NEW.algorithm,NEW.dek_id,NEW.sealed_bytes,NEW.created_at) IS DISTINCT FROM ROW(OLD.org_id,OLD.id,OLD.range_id,OLD.record_id,OLD.version_id,OLD.purpose,OLD.schema_type,OLD.schema_version,OLD.format_version,OLD.algorithm,OLD.dek_id,OLD.sealed_bytes,OLD.created_at) OR NOT EXISTS(SELECT 1 FROM key_rewrap_job WHERE org_id=NEW.org_id AND domain='financial' AND state='migrating' AND target_kek_id=NEW.kek_id AND target_kek_version=NEW.kek_version) THEN RAISE EXCEPTION 'immutable salary range fact'; END IF; RETURN NEW; END$$;
CREATE TRIGGER salary_range_payload_update_guard BEFORE UPDATE OR DELETE ON salary_range_payload FOR EACH ROW EXECUTE FUNCTION salary_range_payload_update_guard();
CREATE FUNCTION compensation_batch_import_candidate_update_guard() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF ROW(NEW.org_id,NEW.id,NEW.batch_id,NEW.subject_id,NEW.base_revision,NEW.line_count,NEW.digest,NEW.record_id,NEW.version_id,NEW.purpose,NEW.schema_type,NEW.schema_version,NEW.format_version,NEW.algorithm,NEW.dek_id,NEW.sealed_bytes,NEW.created_at,NEW.expires_at) IS DISTINCT FROM ROW(OLD.org_id,OLD.id,OLD.batch_id,OLD.subject_id,OLD.base_revision,OLD.line_count,OLD.digest,OLD.record_id,OLD.version_id,OLD.purpose,OLD.schema_type,OLD.schema_version,OLD.format_version,OLD.algorithm,OLD.dek_id,OLD.sealed_bytes,OLD.created_at,OLD.expires_at) OR (ROW(NEW.kek_id,NEW.kek_version,NEW.wrapped_dek) IS DISTINCT FROM ROW(OLD.kek_id,OLD.kek_version,OLD.wrapped_dek) AND NOT EXISTS(SELECT 1 FROM key_rewrap_job WHERE org_id=NEW.org_id AND domain='financial' AND state='migrating' AND target_kek_id=NEW.kek_id AND target_kek_version=NEW.kek_version)) THEN RAISE EXCEPTION 'immutable import candidate'; END IF; RETURN NEW; END$$;
CREATE TRIGGER compensation_batch_import_candidate_update_guard BEFORE UPDATE ON compensation_batch_import_candidate FOR EACH ROW EXECUTE FUNCTION compensation_batch_import_candidate_update_guard();
CREATE TABLE crypto_control(id BIGINT PRIMARY KEY CHECK(id=1),phase TEXT NOT NULL CHECK(phase IN('stable','staged','activated','retiring')),material_generation BIGINT NOT NULL CHECK(material_generation>0),keyring_digest TEXT NOT NULL CHECK(length(keyring_digest)=64),active_json TEXT NOT NULL CHECK(jsonb_typeof(active_json::jsonb)='object'),domain TEXT,manifest_digest BYTEA,target_key_id TEXT,target_key_version BIGINT,updated_at BIGINT NOT NULL,CHECK((phase='stable' AND domain IS NULL AND manifest_digest IS NULL AND target_key_id IS NULL AND target_key_version IS NULL) OR (phase<>'stable' AND domain IS NOT NULL AND octet_length(manifest_digest)=32 AND target_key_id IS NOT NULL AND target_key_version>0)));
CREATE TABLE crypto_material_receipt(kind TEXT NOT NULL CHECK(kind IN('A1','A2','R')),manifest_digest BYTEA NOT NULL CHECK(octet_length(manifest_digest)=32),domain TEXT NOT NULL,target_key_id TEXT NOT NULL,target_key_version BIGINT NOT NULL CHECK(target_key_version>0),material_generation BIGINT NOT NULL CHECK(material_generation>0),keyring_digest TEXT NOT NULL CHECK(length(keyring_digest)=64),active_json TEXT NOT NULL CHECK(jsonb_typeof(active_json::jsonb)='object'),recorded_at BIGINT NOT NULL,PRIMARY KEY(kind,manifest_digest));
